ADMIN_HTML = '<!DOCTYPE html>\n<html lang="es">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Quantum Trading Fleet · Centro de Control Administrativo</title>\n    <style>\n        /* 100% Self-Contained Zero-Dependency CSS */\n        *, *::before, *::after {\n            box-sizing: border-box;\n            margin: 0;\n            padding: 0;\n        }\n\n        :root {\n            --bg-base: #070a13;\n            --bg-surface: #0e1424;\n            --bg-card: #141d33;\n            --bg-card-hover: #1a2540;\n            --border-color: rgba(255, 255, 255, 0.08);\n            --border-focus: #10b981;\n            --text-primary: #f8fafc;\n            --text-secondary: #94a3b8;\n            --text-muted: #64748b;\n            --accent-emerald: #10b981;\n            --accent-emerald-glow: rgba(16, 185, 129, 0.2);\n            --accent-cyan: #06b6d4;\n            --accent-purple: #8b5cf6;\n            --accent-amber: #f59e0b;\n            --accent-red: #ef4444;\n            --radius-lg: 16px;\n            --radius-md: 10px;\n            --radius-sm: 6px;\n            --font-main: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;\n            --font-mono: "JetBrains Mono", "SF Mono", Consolas, "Courier New", monospace;\n        }\n\n        body {\n            background-color: var(--bg-base);\n            color: var(--text-primary);\n            font-family: var(--font-main);\n            min-height: 100vh;\n            line-height: 1.5;\n            -webkit-font-smoothing: antialiased;\n        }\n\n        /* Utility classes */\n        .hidden { display: none !important; }\n\n        /* Login Overlay */\n        #loginOverlay {\n            position: fixed;\n            inset: 0;\n            background: rgba(7, 10, 19, 0.96);\n            backdrop-filter: blur(12px);\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            z-index: 9999;\n            padding: 20px;\n        }\n\n        .login-box {\n            width: 100%;\n            max-width: 440px;\n            background: var(--bg-surface);\n            border: 1px solid var(--border-color);\n            border-radius: var(--radius-lg);\n            padding: 36px;\n            box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.7), 0 0 30px var(--accent-emerald-glow);\n        }\n\n        .login-header {\n            text-align: center;\n            margin-bottom: 28px;\n        }\n\n        .brand-badge {\n            display: inline-flex;\n            align-items: center;\n            justify-content: center;\n            width: 56px;\n            height: 56px;\n            border-radius: 16px;\n            background: linear-gradient(135deg, var(--accent-emerald), var(--accent-cyan));\n            color: #000;\n            font-size: 26px;\n            font-weight: 900;\n            font-family: var(--font-mono);\n            margin-bottom: 16px;\n            box-shadow: 0 10px 20px rgba(16, 185, 129, 0.3);\n        }\n\n        .login-title {\n            font-size: 22px;\n            font-weight: 800;\n            color: #fff;\n            letter-spacing: -0.5px;\n        }\n\n        .login-sub {\n            font-size: 13px;\n            color: var(--text-secondary);\n            margin-top: 6px;\n        }\n\n        .form-group {\n            margin-bottom: 18px;\n        }\n\n        .form-label {\n            display: block;\n            font-size: 11px;\n            font-family: var(--font-mono);\n            text-transform: uppercase;\n            letter-spacing: 0.8px;\n            color: var(--text-secondary);\n            margin-bottom: 8px;\n            font-weight: 600;\n        }\n\n        .form-input, .form-select {\n            width: 100%;\n            padding: 12px 16px;\n            background: var(--bg-card);\n            border: 1px solid var(--border-color);\n            border-radius: var(--radius-md);\n            color: #fff;\n            font-size: 14px;\n            font-family: inherit;\n            transition: all 0.2s;\n            outline: none;\n        }\n\n        .form-input:focus, .form-select:focus {\n            border-color: var(--border-focus);\n            box-shadow: 0 0 0 3px var(--accent-emerald-glow);\n        }\n\n        .form-select option {\n            background: var(--bg-card);\n            color: #fff;\n        }\n\n        .btn-primary {\n            width: 100%;\n            padding: 14px 20px;\n            background: var(--accent-emerald);\n            color: #000;\n            border: none;\n            border-radius: var(--radius-md);\n            font-size: 14px;\n            font-weight: 700;\n            cursor: pointer;\n            transition: all 0.2s;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            gap: 8px;\n            margin-top: 8px;\n        }\n\n        .btn-primary:hover {\n            background: #34d399;\n            transform: translateY(-1px);\n            box-shadow: 0 8px 20px rgba(16, 185, 129, 0.3);\n        }\n\n        .error-banner {\n            background: rgba(239, 68, 68, 0.15);\n            border: 1px solid rgba(239, 68, 68, 0.4);\n            color: #fca5a5;\n            padding: 10px 14px;\n            border-radius: var(--radius-md);\n            font-size: 12px;\n            margin-bottom: 16px;\n            text-align: center;\n        }\n\n        /* Top Navigation Header */\n        .top-navbar {\n            background: rgba(14, 20, 36, 0.85);\n            backdrop-filter: blur(12px);\n            border-bottom: 1px solid var(--border-color);\n            position: sticky;\n            top: 0;\n            z-index: 100;\n        }\n\n        .nav-container {\n            max-width: 1280px;\n            margin: 0 auto;\n            padding: 0 24px;\n            height: 70px;\n            display: flex;\n            align-items: center;\n            justify-content: space-between;\n        }\n\n        .brand-cluster {\n            display: flex;\n            align-items: center;\n            gap: 14px;\n        }\n\n        .nav-logo {\n            width: 40px;\n            height: 40px;\n            border-radius: 12px;\n            background: var(--accent-emerald);\n            color: #000;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-weight: 900;\n            font-size: 18px;\n            font-family: var(--font-mono);\n            box-shadow: 0 4px 12px rgba(16, 185, 129, 0.3);\n        }\n\n        .nav-brand-text h1 {\n            font-size: 16px;\n            font-weight: 800;\n            color: #fff;\n            letter-spacing: -0.2px;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n\n        .role-tag {\n            font-size: 10px;\n            font-family: var(--font-mono);\n            font-weight: 700;\n            padding: 2px 8px;\n            border-radius: 999px;\n            background: rgba(16, 185, 129, 0.15);\n            color: var(--accent-emerald);\n            border: 1px solid rgba(16, 185, 129, 0.3);\n        }\n\n        .nav-brand-text p {\n            font-size: 11px;\n            color: var(--text-secondary);\n        }\n\n        .nav-actions {\n            display: flex;\n            align-items: center;\n            gap: 12px;\n        }\n\n        .status-pill {\n            display: inline-flex;\n            align-items: center;\n            gap: 6px;\n            padding: 6px 12px;\n            border-radius: 999px;\n            background: rgba(16, 185, 129, 0.1);\n            border: 1px solid rgba(16, 185, 129, 0.25);\n            font-size: 12px;\n            font-weight: 600;\n            color: var(--accent-emerald);\n        }\n\n        .pulse-dot {\n            width: 8px;\n            height: 8px;\n            border-radius: 50%;\n            background: var(--accent-emerald);\n            box-shadow: 0 0 8px var(--accent-emerald);\n            animation: pulse 2s infinite;\n        }\n\n        @keyframes pulse {\n            0%, 100% { opacity: 1; transform: scale(1); }\n            50% { opacity: 0.4; transform: scale(1.15); }\n        }\n\n        .btn-outline {\n            padding: 8px 14px;\n            background: var(--bg-card);\n            border: 1px solid var(--border-color);\n            color: var(--text-secondary);\n            border-radius: var(--radius-md);\n            font-size: 12px;\n            font-weight: 600;\n            cursor: pointer;\n            transition: all 0.2s;\n        }\n\n        .btn-outline:hover {\n            background: var(--bg-card-hover);\n            color: #fff;\n            border-color: rgba(255, 255, 255, 0.2);\n        }\n\n        /* Main Container */\n        .main-content {\n            max-width: 1280px;\n            margin: 0 auto;\n            padding: 32px 24px;\n        }\n\n        /* KPI Cards Grid */\n        .kpi-grid {\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n            gap: 20px;\n            margin-bottom: 32px;\n        }\n\n        .kpi-card {\n            background: var(--bg-surface);\n            border: 1px solid var(--border-color);\n            border-radius: var(--radius-lg);\n            padding: 24px;\n            position: relative;\n            overflow: hidden;\n            transition: transform 0.2s, border-color 0.2s;\n        }\n\n        .kpi-card:hover {\n            border-color: rgba(255, 255, 255, 0.15);\n            transform: translateY(-2px);\n        }\n\n        .kpi-header {\n            display: flex;\n            align-items: center;\n            justify-content: space-between;\n            margin-bottom: 12px;\n        }\n\n        .kpi-label {\n            font-size: 11px;\n            font-family: var(--font-mono);\n            text-transform: uppercase;\n            letter-spacing: 0.5px;\n            color: var(--text-secondary);\n            font-weight: 600;\n        }\n\n        .kpi-icon {\n            width: 36px;\n            height: 36px;\n            border-radius: 10px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-size: 16px;\n        }\n\n        .kpi-val {\n            font-size: 32px;\n            font-weight: 800;\n            color: #fff;\n            letter-spacing: -0.5px;\n            line-height: 1.1;\n        }\n\n        .kpi-sub {\n            font-size: 12px;\n            color: var(--text-secondary);\n            margin-top: 8px;\n            display: flex;\n            align-items: center;\n            gap: 6px;\n        }\n\n        /* Progress Bar for $200 USD Goal */\n        .progress-bar-bg {\n            width: 100%;\n            height: 6px;\n            background: rgba(255, 255, 255, 0.08);\n            border-radius: 999px;\n            margin-top: 10px;\n            overflow: hidden;\n        }\n\n        .progress-bar-fill {\n            height: 100%;\n            background: linear-gradient(90deg, var(--accent-emerald), var(--accent-cyan));\n            border-radius: 999px;\n            width: 0%;\n            transition: width 0.5s ease;\n        }\n\n        /* Tab Controls */\n        .tab-bar {\n            display: flex;\n            gap: 10px;\n            border-bottom: 1px solid var(--border-color);\n            margin-bottom: 24px;\n            padding-bottom: 2px;\n        }\n\n        .tab-btn {\n            background: transparent;\n            border: none;\n            color: var(--text-secondary);\n            font-size: 14px;\n            font-weight: 600;\n            padding: 12px 18px;\n            border-radius: var(--radius-md) var(--radius-md) 0 0;\n            cursor: pointer;\n            transition: all 0.2s;\n            position: relative;\n            display: flex;\n            align-items: center;\n            gap: 8px;\n        }\n\n        .tab-btn:hover {\n            color: #fff;\n            background: rgba(255, 255, 255, 0.03);\n        }\n\n        .tab-btn.active {\n            color: var(--accent-emerald);\n            background: rgba(16, 185, 129, 0.08);\n        }\n\n        .tab-btn.active::after {\n            content: "";\n            position: absolute;\n            bottom: -3px;\n            left: 0;\n            right: 0;\n            height: 3px;\n            background: var(--accent-emerald);\n            border-radius: 3px;\n        }\n\n        /* Content Sections */\n        .content-panel {\n            background: var(--bg-surface);\n            border: 1px solid var(--border-color);\n            border-radius: var(--radius-lg);\n            overflow: hidden;\n            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);\n        }\n\n        .panel-header {\n            padding: 20px 24px;\n            border-bottom: 1px solid var(--border-color);\n            display: flex;\n            align-items: center;\n            justify-content: space-between;\n            flex-wrap: wrap;\n            gap: 12px;\n        }\n\n        .panel-title h3 {\n            font-size: 16px;\n            font-weight: 700;\n            color: #fff;\n        }\n\n        .panel-title p {\n            font-size: 12px;\n            color: var(--text-secondary);\n            margin-top: 2px;\n        }\n\n        /* Tables */\n        .table-responsive {\n            width: 100%;\n            overflow-x: auto;\n        }\n\n        table {\n            width: 100%;\n            border-collapse: collapse;\n            text-align: left;\n            font-size: 13px;\n        }\n\n        thead {\n            background: rgba(255, 255, 255, 0.02);\n            border-bottom: 1px solid var(--border-color);\n        }\n\n        th {\n            padding: 14px 20px;\n            font-size: 11px;\n            font-family: var(--font-mono);\n            text-transform: uppercase;\n            letter-spacing: 0.6px;\n            color: var(--text-secondary);\n            font-weight: 600;\n        }\n\n        td {\n            padding: 16px 20px;\n            border-bottom: 1px solid var(--border-color);\n            color: var(--text-primary);\n        }\n\n        tbody tr:hover {\n            background: rgba(255, 255, 255, 0.02);\n        }\n\n        /* Badges */\n        .badge {\n            display: inline-block;\n            padding: 3px 10px;\n            border-radius: 999px;\n            font-size: 11px;\n            font-weight: 700;\n            font-family: var(--font-mono);\n        }\n\n        .badge-trial {\n            background: rgba(6, 182, 212, 0.15);\n            color: var(--accent-cyan);\n            border: 1px solid rgba(6, 182, 212, 0.3);\n        }\n\n        .badge-quarterly {\n            background: rgba(16, 185, 129, 0.15);\n            color: var(--accent-emerald);\n            border: 1px solid rgba(16, 185, 129, 0.3);\n        }\n\n        .badge-lifetime {\n            background: rgba(139, 92, 246, 0.15);\n            color: var(--accent-purple);\n            border: 1px solid rgba(139, 92, 246, 0.3);\n        }\n\n        .badge-active {\n            color: var(--accent-emerald);\n            font-weight: 600;\n            display: inline-flex;\n            align-items: center;\n            gap: 4px;\n        }\n\n        .key-text {\n            font-family: var(--font-mono);\n            font-size: 12px;\n            color: #cbd5e1;\n            background: rgba(0, 0, 0, 0.3);\n            padding: 4px 8px;\n            border-radius: var(--radius-sm);\n            border: 1px solid rgba(255, 255, 255, 0.05);\n            display: inline-block;\n            max-width: 320px;\n            overflow: hidden;\n            text-overflow: ellipsis;\n            white-space: nowrap;\n            user-select: all;\n        }\n\n        .btn-copy-mini {\n            background: transparent;\n            border: 1px solid var(--border-color);\n            color: var(--text-secondary);\n            border-radius: 4px;\n            padding: 3px 8px;\n            font-size: 11px;\n            cursor: pointer;\n            margin-left: 6px;\n            transition: all 0.2s;\n        }\n\n        .btn-copy-mini:hover {\n            color: #fff;\n            border-color: var(--accent-emerald);\n            background: rgba(16, 185, 129, 0.1);\n        }\n\n        /* Issuer Form */\n        .issuer-form-container {\n            max-width: 600px;\n            margin: 0 auto;\n            padding: 36px 24px;\n        }\n\n        .result-box {\n            margin-top: 24px;\n            background: rgba(16, 185, 129, 0.08);\n            border: 1px solid rgba(16, 185, 129, 0.3);\n            border-radius: var(--radius-md);\n            padding: 20px;\n        }\n\n        .result-key-display {\n            font-family: var(--font-mono);\n            font-size: 14px;\n            font-weight: 700;\n            color: #fff;\n            background: #000;\n            padding: 12px 16px;\n            border-radius: var(--radius-sm);\n            margin: 10px 0;\n            word-break: break-all;\n            user-select: all;\n            border: 1px solid rgba(255, 255, 255, 0.1);\n        }\n\n        /* Empty state */\n        .empty-state {\n            padding: 48px 24px;\n            text-align: center;\n            color: var(--text-muted);\n            font-size: 14px;\n        }\n    </style>\n</head>\n<body>\n\n    <!-- 1. LOGIN MODAL OVERLAY -->\n    <div id="loginOverlay">\n        <div class="login-box">\n            <div class="login-header">\n                <div class="brand-badge">Q</div>\n                <h2 class="login-title">Centro de Control Privado</h2>\n                <p class="login-sub">Quantum Trading Fleet · Licencias & Monitor 24/7</p>\n            </div>\n\n            <form id="loginForm">\n                <div id="loginError" class="error-banner hidden"></div>\n                \n                <div class="form-group">\n                    <label class="form-label" for="username">Usuario Administrador</label>\n                    <input type="text" id="username" class="form-input" required value="admin" autocomplete="username">\n                </div>\n\n                <div class="form-group">\n                    <label class="form-label" for="password">Contraseña Maestra</label>\n                    <input type="password" id="password" class="form-input" required placeholder="Introduce tu clave..." autocomplete="current-password">\n                </div>\n\n                <button type="submit" class="btn-primary">\n                    🔐 Desbloquear Panel de Control\n                </button>\n            </form>\n        </div>\n    </div>\n\n    <!-- 2. MAIN DASHBOARD CONTENT -->\n    <div id="dashboardApp" class="hidden">\n        \n        <!-- Navbar -->\n        <header class="top-navbar">\n            <div class="nav-container">\n                <div class="brand-cluster">\n                    <div class="nav-logo">Q</div>\n                    <div class="nav-brand-text">\n                        <h1>COMMAND CENTER <span class="role-tag">ADMIN</span></h1>\n                        <p>Supervisión en Tiempo Real de Ventas y Licencias</p>\n                    </div>\n                </div>\n\n                <div class="nav-actions">\n                    <div class="status-pill">\n                        <span class="pulse-dot"></span>\n                        <span>Bot 24/7 Activo</span>\n                    </div>\n                    <button onclick="refreshDataNow()" class="btn-outline" title="Actualizar datos">\n                        🔄 Refrescar\n                    </button>\n                    <button onclick="clearTestData()" class="btn-outline" style="color: var(--accent-red); border-color: rgba(239, 68, 68, 0.4);" title="Borrar datos de prueba">\n                        🗑️ Limpiar Pruebas\n                    </button>\n                    <button onclick="logout()" class="btn-outline">\n                        Cerrar Sesión\n                    </button>\n                </div>\n            </div>\n        </header>\n\n        <!-- Main Body -->\n        <main class="main-content">\n            \n            <!-- Real-time KPI Cards -->\n            <div class="kpi-grid">\n                \n                <!-- Card 1: Licencias -->\n                <div class="kpi-card">\n                    <div class="kpi-header">\n                        <span class="kpi-label">Licencias Emitidas</span>\n                        <div class="kpi-icon" style="background: rgba(16,185,129,0.15); color: var(--accent-emerald);">🔑</div>\n                    </div>\n                    <div id="kpiTotalLicenses" class="kpi-val">0</div>\n                    <div id="kpiLicensesSub" class="kpi-sub">0 Pruebas · 0 Pagas</div>\n                </div>\n\n                <!-- Card 2: Saldo Solana -->\n                <div class="kpi-card">\n                    <div class="kpi-header">\n                        <span class="kpi-label">Saldo Wallet Solana</span>\n                        <div class="kpi-icon" style="background: rgba(6,182,212,0.15); color: var(--accent-cyan);">⚡</div>\n                    </div>\n                    <div id="kpiSolBalance" class="kpi-val">0.0000 SOL</div>\n                    <div class="kpi-sub" style="font-family: var(--font-mono); font-size: 11px;">2UsQrBL...CQWBMwK</div>\n                </div>\n\n                <!-- Card 3: Actividad Telegram -->\n                <div class="kpi-card">\n                    <div class="kpi-header">\n                        <span class="kpi-label">Eventos Registrados</span>\n                        <div class="kpi-icon" style="background: rgba(139,92,246,0.15); color: var(--accent-purple);">📡</div>\n                    </div>\n                    <div id="kpiTotalEvents" class="kpi-val">0</div>\n                    <div class="kpi-sub">Interacciones @Mi_trading_xauusd_Bot</div>\n                </div>\n\n                <!-- Card 4: Ingresos USD -->\n                <div class="kpi-card">\n                    <div class="kpi-header">\n                        <span class="kpi-label">Ingresos / Meta $200</span>\n                        <div class="kpi-icon" style="background: rgba(245,158,11,0.15); color: var(--accent-amber);">💰</div>\n                    </div>\n                    <div id="kpiRevenue" class="kpi-val">$0.00 USD</div>\n                    <div class="progress-bar-bg">\n                        <div id="kpiProgressBar" class="progress-bar-fill"></div>\n                    </div>\n                    <div id="kpiGoalSub" class="kpi-sub">Objetivo: $200.00 USD (0%)</div>\n                </div>\n\n                <!-- Card 5: Visitas a la Web -->\n                <div class="kpi-card">\n                    <div class="kpi-header">\n                        <span class="kpi-label">Visitas a la Web</span>\n                        <div class="kpi-icon" style="background: rgba(16,185,129,0.15); color: var(--accent-emerald);">🌐</div>\n                    </div>\n                    <div id="kpiTotalViews" class="kpi-val">0</div>\n                    <div class="kpi-sub">Tráfico en Vivo Landing Page</div>\n                </div>\n\n            </div>\n\n            <!-- Tab Buttons -->\n            <div class="tab-bar">\n                <button id="tabBtnLicenses" class="tab-btn active" onclick="switchTab(\'licenses\')">\n                    🔑 Licencias Activas (<span id="tabCountLicenses">0</span>)\n                </button>\n                <button id="tabBtnActivity" class="tab-btn" onclick="switchTab(\'activity\')">\n                    📡 Actividad en Vivo (<span id="tabCountActivity">0</span>)\n                </button>\n                <button id="tabBtnIssuer" class="tab-btn" onclick="switchTab(\'issuer\')">\n                    ⚡ Emitir Nueva Licencia\n                </button>\n            </div>\n\n            <!-- Tab 1: Licenses Table -->\n            <section id="tabLicenses" class="content-panel">\n                <div class="panel-header">\n                    <div class="panel-title">\n                        <h3>Inventario de Licencias y Cuentas MT5</h3>\n                        <p>Supervisa quién tiene acceso, sus números de cuenta autorizados y expiración.</p>\n                    </div>\n                    <input type="text" id="searchLicenses" placeholder="Buscar por cuenta MT5 o cliente..." class="form-input" style="max-width: 280px; padding: 8px 12px; font-size: 12px;" oninput="filterLicenses()">\n                </div>\n                \n                <div class="table-responsive">\n                    <table>\n                        <thead>\n                            <tr>\n                                <th>Nivel / Plan</th>\n                                <th>Cuenta MT5</th>\n                                <th>Clave Criptográfica HMAC</th>\n                                <th>Expiración</th>\n                                <th>Comprador / Usuario</th>\n                                <th>Estado</th>\n                            </tr>\n                        </thead>\n                        <tbody id="licensesTableBody">\n                            <tr><td colspan="6" class="empty-state">Cargando inventario de licencias...</td></tr>\n                        </tbody>\n                    </table>\n                </div>\n            </section>\n\n            <!-- Tab 2: Activity Feed -->\n            <section id="tabActivity" class="content-panel hidden">\n                <div class="panel-header">\n                    <div class="panel-title">\n                        <h3>Feed de Actividad en Vivo de Telegram</h3>\n                        <p>Registro de comandos ejecutados, peticiones de prueba gratuita y escaneos de contratos.</p>\n                    </div>\n                </div>\n                \n                <div class="table-responsive">\n                    <table>\n                        <thead>\n                            <tr>\n                                <th>Fecha y Hora (UTC)</th>\n                                <th>Tipo de Evento</th>\n                                <th>Usuario Telegram</th>\n                                <th>Detalles del Evento</th>\n                            </tr>\n                        </thead>\n                        <tbody id="activityTableBody">\n                            <tr><td colspan="4" class="empty-state">Cargando actividad reciente...</td></tr>\n                        </tbody>\n                    </table>\n                </div>\n            </section>\n\n            <!-- Tab 3: Manual License Issuer -->\n            <section id="tabIssuer" class="content-panel hidden">\n                <div class="panel-header">\n                    <div class="panel-title">\n                        <h3>Generador Criptográfico de Licencias</h3>\n                        <p>Emite al instante una clave firmada con HMAC-SHA256 lista para entregar a un comprador.</p>\n                    </div>\n                </div>\n                \n                <div class="issuer-form-container">\n                    <form id="issueLicenseForm">\n                        <div class="form-group">\n                            <label class="form-label" for="issueMt5Account">Número de Cuenta MT5 del Cliente</label>\n                            <input type="text" id="issueMt5Account" class="form-input" required placeholder="Ej. 52984982 (o escribe \'ANY\' para comodín)">\n                        </div>\n\n                        <div class="form-group">\n                            <label class="form-label" for="issueTier">Nivel / Duración del Plan</label>\n                            <select id="issueTier" class="form-select">\n                                <option value="QUARTERLY">💳 Trimestral (90 Días) - $49 USD</option>\n                                <option value="LIFETIME">👑 Vitalicia Perpetua (Hasta 2099) - $99 USD</option>\n                                <option value="TRIAL">🎁 Prueba Gratuita (7 Días) - $0 USD</option>\n                                <option value="ANNUAL">📅 Anual (365 Días) - $149 USD</option>\n                            </select>\n                        </div>\n\n                        <div class="form-group">\n                            <label class="form-label" for="issueCustomer">Nombre o Telegram del Comprador</label>\n                            <input type="text" id="issueCustomer" class="form-input" placeholder="Ej. @trader_pro o Whop Order #102">\n                        </div>\n\n                        <button type="submit" class="btn-primary">\n                            ⚡ Generar y Registrar Licencia\n                        </button>\n                    </form>\n\n                    <div id="issueResultBox" class="result-box hidden">\n                        <div style="font-weight: 700; color: var(--accent-emerald); font-size: 14px;">✅ ¡Licencia Generada y Registrada con Éxito!</div>\n                        <p style="font-size: 12px; color: var(--text-secondary); margin-top: 4px;">Copia esta clave y entrégasela al cliente:</p>\n                        <div id="issueResultKey" class="result-key-display"></div>\n                        <button onclick="copyGeneratedKey()" class="btn-outline" style="width: 100%; justify-content: center; padding: 10px;">\n                            📋 Copiar Clave al Portapapeles\n                        </button>\n                    </div>\n                </div>\n            </section>\n\n        </main>\n\n    </div>\n\n    <!-- 3. SCRIPT LOGIC -->\n    <script>\n        let authToken = localStorage.getItem(\'quantum_admin_token\') || \'\';\n        let allLicenses = [];\n\n        // Check authentication state on page load\n        window.addEventListener(\'DOMContentLoaded\', () => {\n            if (authToken) {\n                showDashboard();\n            } else {\n                document.getElementById(\'loginOverlay\').classList.remove(\'hidden\');\n                document.getElementById(\'dashboardApp\').classList.add(\'hidden\');\n            }\n        });\n\n        // Handle Login Submission\n        document.getElementById(\'loginForm\').addEventListener(\'submit\', async (e) => {\n            e.preventDefault();\n            const u = document.getElementById(\'username\').value.trim();\n            const p = document.getElementById(\'password\').value.trim();\n            const errBox = document.getElementById(\'loginError\');\n            errBox.classList.add(\'hidden\');\n\n            try {\n                const res = await fetch(\'/api/admin/login\', {\n                    method: \'POST\',\n                    headers: {\'Content-Type\': \'application/json\'},\n                    body: JSON.stringify({username: u, password: p})\n                });\n                const data = await res.json();\n                if (data.ok && data.token) {\n                    authToken = data.token;\n                    localStorage.setItem(\'quantum_admin_token\', authToken);\n                    showDashboard();\n                } else {\n                    errBox.textContent = data.error || \'Credenciales incorrectas.\';\n                    errBox.classList.remove(\'hidden\');\n                }\n            } catch (err) {\n                errBox.textContent = \'Error conectando con el servidor. Intenta nuevamente.\';\n                errBox.classList.remove(\'hidden\');\n            }\n        });\n\n        function showDashboard() {\n            document.getElementById(\'loginOverlay\').classList.add(\'hidden\');\n            document.getElementById(\'dashboardApp\').classList.remove(\'hidden\');\n            loadDashboardData();\n            // Polling every 12 seconds\n            if (!window._dashboardTimer) {\n                window._dashboardTimer = setInterval(loadDashboardData, 12000);\n            }\n        }\n\n        function logout() {\n            localStorage.removeItem(\'quantum_admin_token\');\n            authToken = \'\';\n            location.reload();\n        }\n\n        function refreshDataNow() {\n            loadDashboardData();\n        }\n\n        async function clearTestData() {\n            if (!confirm(\'¿Deseas limpiar todos los registros de prueba y dejar el panel en blanco para los clientes reales?\')) return;\n            try {\n                const res = await fetch(\'/api/admin/clear-data\', {\n                    method: \'POST\',\n                    headers: {\'Authorization\': \'Bearer \' + authToken}\n                });\n                const d = await res.json();\n                if (d.ok) {\n                    alert(\'¡Registros de prueba eliminados! El panel está 100% limpio.\');\n                    loadDashboardData();\n                } else {\n                    alert(\'Error: \' + (d.error || \'No autorizado\'));\n                }\n            } catch (e) {\n                alert(\'Error al conectar con el servidor: \' + e.message);\n            }\n        }\n\n        async function loadDashboardData() {\n            if (!authToken) return;\n            try {\n                const res = await fetch(\'/api/admin/data\', {\n                    headers: {\'Authorization\': \'Bearer \' + authToken}\n                });\n                if (res.status === 401) {\n                    logout();\n                    return;\n                }\n                const d = await res.json();\n                if (d.ok) {\n                    renderDashboard(d);\n                }\n            } catch (e) {\n                console.error(\'Error fetching admin data:\', e);\n            }\n        }\n\n        function renderDashboard(d) {\n            // Update KPIs\n            const s = d.summary || {};\n            document.getElementById(\'kpiTotalLicenses\').textContent = s.total_licenses || 0;\n            document.getElementById(\'kpiLicensesSub\').textContent = `${s.trial_licenses || 0} Pruebas · ${s.paid_licenses || 0} Pagas`;\n            document.getElementById(\'kpiSolBalance\').textContent = `${(s.sol_balance || 0).toFixed(4)} SOL`;\n            document.getElementById(\'kpiTotalEvents\').textContent = s.total_events || 0;\n            if (document.getElementById(\'kpiTotalViews\')) {\n                document.getElementById(\'kpiTotalViews\').textContent = s.total_page_views || 0;\n            }\n            \n            const rev = s.total_revenue_usd || 0;\n            document.getElementById(\'kpiRevenue\').textContent = `$${rev.toFixed(2)} USD`;\n            const pct = Math.min(100, Math.round((rev / 200) * 100));\n            document.getElementById(\'kpiProgressBar\').style.width = pct + \'%\';\n            document.getElementById(\'kpiGoalSub\').textContent = `Objetivo: $200.00 USD (${pct}%)`;\n\n            // Tab badge counts\n            document.getElementById(\'tabCountLicenses\').textContent = (d.licenses || []).length;\n            document.getElementById(\'tabCountActivity\').textContent = (d.activity || []).length;\n\n            // Render Licenses\n            allLicenses = d.licenses || [];\n            renderLicensesTable(allLicenses);\n\n            // Render Activity\n            renderActivityTable(d.activity || []);\n        }\n\n        function renderLicensesTable(list) {\n            const tbody = document.getElementById(\'licensesTableBody\');\n            if (!list || list.length === 0) {\n                tbody.innerHTML = \'<tr><td colspan="6" class="empty-state">No hay licencias registradas aún.</td></tr>\';\n                return;\n            }\n            tbody.innerHTML = list.map(l => {\n                let badgeClass = \'badge-quarterly\';\n                if (l.tier === \'TRIAL\') badgeClass = \'badge-trial\';\n                else if (l.tier === \'LIFETIME\') badgeClass = \'badge-lifetime\';\n\n                return `\n                    <tr>\n                        <td><span class="badge ${badgeClass}">${l.tier}</span></td>\n                        <td style="font-weight: 700; color: #fff;">#${l.mt5_account}</td>\n                        <td>\n                            <span class="key-text" title="${l.key}">${l.key}</span>\n                            <button class="btn-copy-mini" onclick="copyText(\'${l.key}\')">Copiar</button>\n                        </td>\n                        <td style="color: var(--text-secondary); font-family: var(--font-mono); font-size: 12px;">${l.expiry}</td>\n                        <td style="font-weight: 500;">${l.customer || \'Cliente\'}</td>\n                        <td><span class="badge-active">🟢 ${l.status || \'ACTIVA\'}</span></td>\n                    </tr>\n                `;\n            }).join(\'\');\n        }\n\n        function renderActivityTable(acts) {\n            const tbody = document.getElementById(\'activityTableBody\');\n            if (!acts || acts.length === 0) {\n                tbody.innerHTML = \'<tr><td colspan="4" class="empty-state">Sin eventos recientes.</td></tr>\';\n                return;\n            }\n            tbody.innerHTML = acts.slice(0, 40).map(a => `\n                <tr>\n                    <td style="color: var(--text-secondary); font-family: var(--font-mono); font-size: 12px; white-space: nowrap;">${a.timestamp}</td>\n                    <td><span class="badge badge-trial">${a.event_type}</span></td>\n                    <td style="font-weight: 700; color: #fff;">${a.username || a.user_id}</td>\n                    <td style="color: var(--text-secondary); word-break: break-word;">${a.details}</td>\n                </tr>\n            `).join(\'\');\n        }\n\n        function filterLicenses() {\n            const q = document.getElementById(\'searchLicenses\').value.toLowerCase().trim();\n            if (!q) {\n                renderLicensesTable(allLicenses);\n                return;\n            }\n            const filtered = allLicenses.filter(l => \n                (l.mt5_account || \'\').toLowerCase().includes(q) || \n                (l.customer || \'\').toLowerCase().includes(q) ||\n                (l.key || \'\').toLowerCase().includes(q)\n            );\n            renderLicensesTable(filtered);\n        }\n\n        function switchTab(t) {\n            [\'licenses\', \'activity\', \'issuer\'].forEach(x => {\n                const tabEl = document.getElementById(\'tab\' + x.charAt(0).toUpperCase() + x.slice(1));\n                const btnEl = document.getElementById(\'tabBtn\' + x.charAt(0).toUpperCase() + x.slice(1));\n                if (x === t) {\n                    tabEl.classList.remove(\'hidden\');\n                    btnEl.classList.add(\'active\');\n                } else {\n                    tabEl.classList.add(\'hidden\');\n                    btnEl.classList.remove(\'active\');\n                }\n            });\n        }\n\n        // Issue License Form\n        document.getElementById(\'issueLicenseForm\').addEventListener(\'submit\', async (e) => {\n            e.preventDefault();\n            const acc = document.getElementById(\'issueMt5Account\').value.trim();\n            const tier = document.getElementById(\'issueTier\').value;\n            const cust = document.getElementById(\'issueCustomer\').value.trim();\n\n            try {\n                const res = await fetch(\'/api/admin/generate-license\', {\n                    method: \'POST\',\n                    headers: {\n                        \'Content-Type\': \'application/json\',\n                        \'Authorization\': \'Bearer \' + authToken\n                    },\n                    body: JSON.stringify({mt5_account: acc, tier: tier, customer: cust})\n                });\n                const d = await res.json();\n                if (d.ok && d.key) {\n                    document.getElementById(\'issueResultKey\').textContent = d.key;\n                    document.getElementById(\'issueResultBox\').classList.remove(\'hidden\');\n                    loadDashboardData();\n                } else {\n                    alert(\'Error generando licencia: \' + (d.error || \'Desconocido\'));\n                }\n            } catch (err) {\n                alert(\'Error conectando con la API: \' + err.message);\n            }\n        });\n\n        function copyText(txt) {\n            navigator.clipboard.writeText(txt);\n            alert(\'¡Clave copiada al portapapeles!\');\n        }\n\n        function copyGeneratedKey() {\n            const k = document.getElementById(\'issueResultKey\').textContent;\n            copyText(k);\n        }\n    </script>\n</body>\n</html>\n'
